<body>
  <a class="skip-link" href="#maincontent">Skip to main content</a>
  <main id="maincontent">
    <div class="page-shell">
      <header class="hero">
        <p class="eyebrow">Support</p>
        <h1>Contact our support team</h1>
        <p class="lede">Send a request and we will respond as soon as possible. Share the best way to reach you so the team can follow up without delay.</p>
      </header>

      <section class="card" aria-labelledby="support-form-title">
        <h2 id="support-form-title" class="sr-only">Support request form</h2>
        <div id="form-status" class="status" hidden role="status" aria-live="polite"></div>

        <form id="support-form" class="form-grid" novalidate>
          <div class="form-field">
            <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
            <input
              id="full-name"
              name="fullName"
              type="text"
              autocomplete="name"
              required
            >
            <p id="full-name-error" class="error-text" hidden>Error: Enter your full name.</p>
          </div>

          <div class="form-field">
            <label for="email-address">Email address <span class="required" aria-hidden="true">*</span></label>
            <input
              id="email-address"
              name="emailAddress"
              type="email"
              autocomplete="email"
              required
            >
            <p id="email-address-error" class="error-text" hidden>Error: Enter a valid email address, such as name@example.com.</p>
          </div>

          <div class="form-field">
            <label for="phone-number">Phone number <span aria-hidden="true">(optional)</span></label>
            <input
              id="phone-number"
              name="phoneNumber"
              type="tel"
              autocomplete="tel"
              inputmode="tel"
              aria-describedby="phone-number-help"
            >
            <p id="phone-number-help" class="help-text">Format: include country code if needed, such as +1 555 123 4567 or (555) 123-4567.</p>
          </div>

          <div class="actions">
            <button class="button" type="submit">Send request</button>
            <p class="subtle-note">Required fields are marked with an asterisk.</p>
          </div>
        </form>
      </section>
    </div>
  </main>

  <script>
    (function () {
      const form = document.getElementById('support-form');
      const status = document.getElementById('form-status');
      const fields = {
        fullName: {
          input: document.getElementById('full-name'),
          error: document.getElementById('full-name-error')
        },
        emailAddress: {
          input: document.getElementById('email-address'),
          error: document.getElementById('email-address-error')
        },
        phoneNumber: {
          input: document.getElementById('phone-number')
        }
      };

      const submittedState = new WeakMap();

      function setFieldError(input, errorNode, message) {
        if (message) {
          input.setAttribute('aria-invalid', 'true');
          errorNode.textContent = message;
          errorNode.hidden = false;
          input.setAttribute('aria-describedby', errorNode.id);
          return;
        }

        input.removeAttribute('aria-invalid');
        errorNode.hidden = true;
        input.removeAttribute('aria-describedby');
      }

      function validateField(input) {
        if (input.validity.valueMissing) {
          return input.id === 'full-name'
            ? 'Error: Enter your full name.'
            : 'Error: Enter your email address.';
        }

        if (input.validity.typeMismatch) {
          return 'Error: Enter a valid email address, such as name@example.com.';
        }

        return '';
      }

      function updateField(input) {
        const field = Object.values(fields).find(({ input: fieldInput }) => fieldInput === input);
        if (!field || !field.error) {
          return;
        }

        const shouldValidate = submittedState.get(form) === true;
        const message = shouldValidate ? validateField(input) : '';
        setFieldError(input, field.error, message);
      }

      form.addEventListener('submit', function (event) {
        event.preventDefault();
        submittedState.set(form, true);

        const fullNameError = validateField(fields.fullName.input);
        const emailError = validateField(fields.emailAddress.input);

        setFieldError(fields.fullName.input, fields.fullName.error, fullNameError);
        setFieldError(fields.emailAddress.input, fields.emailAddress.error, emailError);

        if (fullNameError || emailError) {
          (fullNameError ? fields.fullName.input : fields.emailAddress.input).focus();
          status.hidden = true;
          status.textContent = '';
          return;
        }

        status.textContent = 'Thanks — your request is ready to send.';
        status.hidden = false;
      });

      fields.fullName.input.addEventListener('input', function () {
        updateField(this);
      });

      fields.emailAddress.input.addEventListener('input', function () {
        updateField(this);
      });
    })();
  </script>
</body>
