const fs = require('fs');
const path = require('path');
const { chromium } = require('playwright');
const axe = require('axe-core');

(async () => {
  const browser = await chromium.launch({headless: true});
  const page = await browser.newPage();
  const html = fs.readFileSync(path.resolve('index.html'), 'utf8');
  await page.setContent(html, { waitUntil: 'load' });
  await page.addScriptTag({ content: axe.source });
  const results = await page.evaluate(async () => await window.axe.run());
  const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));

  const checks = await page.evaluate(() => {
    const form = document.querySelector('form');
    const inputs = Array.from(form.querySelectorAll('input'));
    const phoneHelp = document.getElementById('phone-number-help')?.textContent || '';
    return {
      formFieldCount: document.querySelectorAll('.form-field').length,
      hiddenErrorsInitially: Array.from(document.querySelectorAll('.error-text')).every(el => el.hidden),
      requiredFields: inputs.filter(el => el.required).map(el => el.id),
      phoneHelp,
      labels: inputs.map(el => document.querySelector(`label[for="${el.id}"]`)?.textContent.trim() || null),
    };
  });

  await page.click('button[type="submit"]');
  const submitChecks = await page.evaluate(() => ({
    activeId: document.activeElement.id,
    fullNameInvalid: document.getElementById('full-name').getAttribute('aria-invalid'),
    emailInvalid: document.getElementById('email-address').getAttribute('aria-invalid'),
    visibleErrors: Array.from(document.querySelectorAll('.error-text')).filter(el => !el.hidden).length,
  }));

  console.log(JSON.stringify({ violations: wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })), checks, submitChecks }));
  await browser.close();
  process.exit(wcag.length ? 1 : 0);
})().catch(err => {
  console.error(err);
  process.exit(1);
});
